    case "rect":   return s.w * s.h;
    default:       return assertNever(s); // new variant = compile error
  }
};

interface ShapeVisitor<R> { visitCircle(c: Circle): R; visitRect(r: Rect): R }
abstract class Shape { abstract accept<R>(v: ShapeVisitor<R>): R; }
class Circle extends Shape {
  constructor(readonly r: number) { super(); }
  accept<R>(v: ShapeVisitor<R>): R { return v.visitCircle(this); }   // 2nd dispatch
}

class AreaVisitor implements ShapeVisitor<number> {          // one operation
  visitCircle(c: Circle) { return Math.PI * c.r ** 2; }
  visitRect(r: Rect) { return r.w * r.h; }
}
const area = shape.accept(new AreaVisitor());
